def _component_06():
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        best = [None, None]

        def is_acyclic(edges, names):
            active, done = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in names)

        def search(assigned, constraints):
            for name, version in assigned.items():
                if any(not low <= version <= high
                       for low, high in constraints.get(name, [])):
                    return
            unresolved = sorted(set(constraints) - set(assigned))
            if not unresolved:
                edges = {}
                for name, version in assigned.items():
                    row = next(r for r in packages[name] if r["version"] == version)
                    edges[name] = []
                    for dep in row.get("deps", []):
                        feature = dep.get("feature", "")
                        if not feature or feature in features:
                            edges[name].append(dep["name"])
                if not is_acyclic(edges, assigned):
                    return
                names = sorted(packages)
                vector = tuple(assigned.get(name, -1) for name in names)
                if best[0] is None or vector < best[0]:
                    best[:] = [vector, dict(assigned)]
                return

            name = unresolved[0]
            ranges = constraints[name]
            rows = sorted(packages.get(name, []), key=lambda r: r["version"])
            for row in rows:
                version = row["version"]
                if any(not low <= version <= high for low, high in ranges):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                next_assigned = dict(assigned)
                next_assigned[name] = version
                next_constraints = {key: list(value) for key, value in constraints.items()}
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    next_constraints.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"]))
                search(next_assigned, next_constraints)

        roots = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        search({}, roots)
        if best[1] is None:
            return {"error": "unsatisfiable"}
        return {"versions": best[1]}

    return solve


def _component_07():
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if mandatory & blocked:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        best_ids = None
        best_value = None
        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            intervals = sorted((job["start"], job["end"]) for job in subset)
            if any(intervals[i][0] < intervals[i - 1][1]
                   for i in range(1, len(intervals))):
                continue
            selected = tuple(sorted(ids))
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


def _component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], data["coupons"], initial_mask)
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], data["coupons"], initial_mask)]
        while queue:
            arrival, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and remaining == 0 and mask == full:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, remaining - 1))
                next_mask = mask | bit.get(edge["v"], 0)
                for duration, next_remaining in choices:
                    next_arrival = depart + duration
                    if next_arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_remaining, next_mask)
                    if next_arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = next_arrival
                        heapq.heappush(queue, (next_arrival, edge["v"],
                                               next_remaining, next_mask))
        return {"arrival": None}

    return solve


